import os
import requests


PAYMENT_API_URL = os.environ.get("STRIPE_API_URL", "https://api.stripe.com/v1")
STRIPE_SECRET_KEY = os.environ["STRIPE_SECRET_KEY"]  # fail fast if missing
STRIPE_WEBHOOK_SECRET = os.environ["STRIPE_WEBHOOK_SECRET"]


class PaymentGateway:
    def __init__(self, api_key: str = None, ca_bundle: str = None):
        self.api_key = api_key or STRIPE_SECRET_KEY
        self.base_url = PAYMENT_API_URL
        # Allow custom CA bundle for internal PKI; default uses system CAs
        self.verify = ca_bundle if ca_bundle else True

    def _headers(self):
        return {"Authorization": f"Bearer {self.api_key}"}

    def charge_customer(self, customer_id: str, amount_cents: int, currency: str = "usd"):
        response = requests.post(
            f"{self.base_url}/charges",
            headers=self._headers(),
            data={
                "customer": customer_id,
                "amount": amount_cents,
                "currency": currency,
            },
            verify=self.verify,
        )
        response.raise_for_status()
        return response.json()

    def create_refund(self, charge_id: str, amount_cents: int = None):
        payload = {"charge": charge_id}
        if amount_cents:
            payload["amount"] = amount_cents
        response = requests.post(
            f"{self.base_url}/refunds",
            headers=self._headers(),
            data=payload,
            verify=self.verify,
        )
        response.raise_for_status()
        return response.json()

    def get_customer(self, customer_id: str):
        response = requests.get(
            f"{self.base_url}/customers/{customer_id}",
            headers=self._headers(),
            verify=self.verify,
        )
        response.raise_for_status()
        return response.json()

    def create_payment_intent(self, amount_cents: int, currency: str, metadata: dict = None):
        data = {"amount": amount_cents, "currency": currency}
        if metadata:
            for k, v in metadata.items():
                data[f"metadata[{k}]"] = v
        response = requests.post(
            f"{self.base_url}/payment_intents",
            headers=self._headers(),
            data=data,
            verify=self.verify,
        )
        response.raise_for_status()
        return response.json()

