                "SELECT id, email, name, role FROM users WHERE name LIKE ? AND role = ?",
                (f"%{name_pattern}%", role)
            )
        else:
            cursor = self.conn.execute(
                "SELECT id, email, name, role FROM users WHERE name LIKE ?",
                (f"%{name_pattern}%",)
            )
        return [User(*row) for row in cursor.fetchall()]

    def update_user_role(self, user_id: int, new_role: str):
        self.conn.execute(
            "UPDATE users SET role = ? WHERE id = ?",
            (new_role, user_id)
        )
        self.conn.commit()

    def create_user(self, email: str, name: str, password_hash: str, role: str = "user"):
        self.conn.execute(
            "INSERT INTO users (email, name, password_hash, role) VALUES (?, ?, ?, ?)",
            (email, name, password_hash, role)
        )
        self.conn.commit()

    def delete_inactive_users(self, days: int = 90):
        cursor = self.conn.execute(
            "DELETE FROM users WHERE last_login < datetime('now', ? || ' days') AND role != 'admin'",
            (f"-{days}",)
        )
        self.conn.commit()
        return cursor.rowcount

    def get_users_by_ids(self, user_ids: list):
        placeholders = ", ".join("?" for _ in user_ids)
        cursor = self.conn.execute(
            f"SELECT id, email, name, role FROM users WHERE id IN ({placeholders})",
            tuple(user_ids)
        )
        return [User(*row) for row in cursor.fetchall()]

import json
import logging
import redis

logger = logging.getLogger(__name__)


class SessionStore:
    """Redis-backed session storage using JSON serialization."""

    def __init__(self, redis_client: redis.Redis, prefix: str = "session:", ttl: int = 3600):
        self.redis = redis_client
        self.prefix = prefix
        self.ttl = ttl

    def _key(self, session_id: str) -> str:
        return f"{self.prefix}{session_id}"

    def save(self, session_id: str, data: dict):
        raw = json.dumps(data, default=str)
        self.redis.setex(self._key(session_id), self.ttl, raw)

    def load(self, session_id: str) -> dict | None:
        raw = self.redis.get(self._key(session_id))
        if raw is None:
            return None
        try:
            return json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError):
            # Legacy pickle session — decode for backward compat during migration
            # Remove this fallback after one full TTL cycle (1 hour)
            import pickle  # noqa: S403 — transitional only
            try:
                data = pickle.loads(raw)  # noqa: S301
                # Re-save as JSON so it won't hit this path again
                self.save(session_id, data)
                logger.info("Migrated pickle session to JSON: %s", session_id)
                return data
            except Exception:
                logger.warning("Failed to load session %s, discarding", session_id)
                self.delete(session_id)
                return None

    def delete(self, session_id: str):
        self.redis.delete(self._key(session_id))

    def extend(self, session_id: str):
        self.redis.expire(self._key(session_id), self.ttl)

    def bulk_save(self, sessions: dict[str, dict]):
        pipe = self.redis.pipeline()
        for session_id, data in sessions.items():
            raw = json.dumps(data, default=str)
            pipe.setex(self._key(session_id), self.ttl, raw)
        pipe.execute()

    def bulk_load(self, session_ids: list[str]) -> dict[str, dict | None]:
        pipe = self.redis.pipeline()
        for sid in session_ids:
            pipe.get(self._key(sid))
        results = pipe.execute()
        output = {}
        for sid, raw in zip(session_ids, results):
            if raw is not None:
                try:
                    output[sid] = json.loads(raw)
                except (json.JSONDecodeError, UnicodeDecodeError):
                    output[sid] = self.load(sid)  # triggers migration path
            else:
                output[sid] = None
        return output

import hashlib
import hmac
import json
import logging
import os
import secrets
import time

logger = logging.getLogger(__name__)

TOKEN_SECRET = os.environ.get("TOKEN_SECRET", "")
if not TOKEN_SECRET:
    logger.critical("TOKEN_SECRET not set — token operations will fail")


class TokenManager:
    def __init__(self, secret: str = None):
        self.secret = (secret or TOKEN_SECRET).encode()

    def _sign(self, payload: str) -> str:
        """HMAC-SHA256 signature."""
        return hmac.new(self.secret, payload.encode(), hashlib.sha256).hexdigest()

    def generate_token(self, user_id: int, expires_in: int = 3600) -> str:
        timestamp = int(time.time())
        expiry = timestamp + expires_in
        payload = f"{user_id}:{timestamp}:{expiry}"
        signature = self._sign(payload)
        return f"{payload}:{signature}"

    def verify_token(self, token: str) -> int | None:
        parts = token.split(":")
        if len(parts) != 4:
            return None
        user_id_str, timestamp, expiry, signature = parts
        try:
            if int(expiry) < time.time():
                return None
        except ValueError:
            return None
        payload = f"{user_id_str}:{timestamp}:{expiry}"
        expected = self._sign(payload)
        if hmac.compare_digest(signature, expected):
            try:
                return int(user_id_str)
            except ValueError:
                return None
        return None

    def refresh_token(self, token: str, extends_by: int = 3600) -> str | None:
        user_id = self.verify_token(token)
        if user_id is not None:
            return self.generate_token(user_id, extends_by)
        return None

    def revoke_token(self, token: str):
        # Stateless tokens cannot be revoked without a blocklist.
        # TODO: implement token blocklist in Redis
        logger.warning("Token revocation requested but not implemented (stateless tokens)")

    def generate_api_key(self, user_id: int) -> str:
        raw = secrets.token_urlsafe(32)
        return f"isk1_{user_id}_{raw}"

    def validate_api_key(self, api_key: str) -> int | None:
        """Extract user_id from API key. Caller MUST verify against stored keys."""
        parts = api_key.split("_", maxsplit=2)
        if len(parts) == 3 and parts[0] == "isk1":
            try:
                return int(parts[1])
            except ValueError:
                logger.warning("Malformed API key: non-integer user_id")
                return None
        return None
